#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Pinned inputs. To update one, change it and its hash together.
#   Node: https://nodejs.org/dist/v<version>/SHASUMS256.txt, the win-x64.zip line
#   AInakupo: a commit on main of v1be-coding/ainakupo with src/keys/cli.ts
NODE_VERSION="24.22.2"
NODE_ZIP_SHA256="ca1bff5d8ead13c9f2ea404a176db46bd430704d5b5113734049fa365e7799e2"
AINAKUPO_COMMIT="1da1a227c0736c81dd4d6d235b440b89a6bc8860"
REGION="ap-southeast-1"
CLUSTER_NAME="v1be-ainakupo-api-production"

run_wizard() {

TOTAL_STAGES=6
EPISODE="${1:-}"
export AWS_PROFILE="v1be-admin"
MEMBER_PROFILE="v1be-admin-portfolio"
PARAMS=("/$EPISODE/ainakupo/production-key" "/$EPISODE/ainakupo/preview-key")

# Owner logins happen only in Windows Sandbox (ADR-0012).
if [[ ! -d /c/code/v1be-infra/sandbox ]]; then
  warn "Stopping: this isn't Windows Sandbox. Open v1be-admin.wsb and run it there."
  exit 1
fi
if [[ ! "$EPISODE" =~ ^[a-z0-9-]{1,50}$ ]]; then
  warn "Usage: ainakupo-keys.sh <episode>, such as ainakupo-keys.sh portfolio-site"
  exit 1
fi
if [[ "$EPISODE" == "test-episode" || "$EPISODE" == "ainakupo" ]]; then
  warn "Stopping: $EPISODE isn't a sending episode. test-episode's keys come from test-keys.sh."
  exit 1
fi

WORK="$(mktemp -d)"
trap 'cd /; rm -rf "$WORK"' EXIT

banner "$EPISODE: AInakupo ingest keys"

stage "Before you start"
say "This runs AInakupo's keys:add for $EPISODE (ADR-0003 in v1be-coding/ainakupo)."
say "It makes a production key and a preview key, writes them as SecureStrings to:"
for p in "${PARAMS[@]}"; do note "  $p"; done
say "and stores only their SHA-256 hashes in AInakupo's production database."
note "You copy nothing, and no key is shown. The script prints only hints like"
note "aik_prod_…abcd, which are safe to share with Claude."
note "It refuses an episode that already has keys: rotation isn't supported yet."
pause

stage "Get Node and build the key script"
say "The Sandbox has no Node, so this fetches Node $NODE_VERSION and builds keys:add"
say "from AInakupo commit ${AINAKUPO_COMMIT:0:7}. It happens before you sign in to AWS,"
say "and npm runs with install scripts off."
NODE_ZIP="$WORK/node.zip"
curl -fsSL --retry 3 "https://nodejs.org/dist/v$NODE_VERSION/node-v$NODE_VERSION-win-x64.zip" > "$NODE_ZIP"
if [[ "$(sha256sum "$NODE_ZIP" | cut -d' ' -f1)" != "$NODE_ZIP_SHA256" ]]; then
  warn "Stopping: the Node download's hash doesn't match. Nothing was changed."
  exit 1
fi
powershell.exe -NoProfile -Command "Expand-Archive -Force -Path '$(cygpath -w "$NODE_ZIP")' -DestinationPath '$(cygpath -w "$WORK")'"
NODE_DIR="$WORK/node-v$NODE_VERSION-win-x64"
export PATH="$NODE_DIR:$PATH"
say "PASS: Node $(node --version | tr -d '\r'), hash checked"

git clone --quiet https://github.com/v1be-coding/ainakupo "$WORK/ainakupo"
git -C "$WORK/ainakupo" -c advice.detachedHead=false checkout --quiet "$AINAKUPO_COMMIT"
cd "$WORK/ainakupo"
npm ci --ignore-scripts --no-audit --no-fund --loglevel=error
# The same build as package.json's keys:add, without running it yet.
node node_modules/esbuild/bin/esbuild src/keys/cli.ts --bundle --platform=node \
  --target=node24 --format=cjs --external:pg-native --log-level=warning \
  --outfile=dist/keys/add.cjs
say "PASS: built keys:add from ${AINAKUPO_COMMIT:0:7}"
pause

stage "Sign in as v1be-admin"
if ! aws configure get sso_session --profile "$AWS_PROFILE" >/dev/null 2>&1 \
  && ! aws configure get sso_start_url --profile "$AWS_PROFILE" >/dev/null 2>&1; then
  warn "Stopping: this Sandbox has no $AWS_PROFILE profile. Run identity-center.sh, then come back."
  exit 1
fi
if aws sts get-caller-identity --profile "$AWS_PROFILE" >/dev/null 2>&1; then
  say "Already signed in to AWS."
else
  step "A browser opens. Sign in and allow the request."
  aws sso login --profile "$AWS_PROFILE"
fi
ACCOUNT_ID="$(aws organizations list-accounts --query "Accounts[?Name=='portfolio'].Id | [0]" --output text | tr -d '\r')"
if [[ ! "$ACCOUNT_ID" =~ ^[0-9]{12}$ ]]; then
  warn "Stopping: no account is named portfolio."
  exit 1
fi
for key in sso_session sso_start_url sso_region region; do
  value="$(aws configure get "$key" --profile "$AWS_PROFILE" 2>/dev/null | tr -d '\r' || true)"
  if [[ -n "$value" ]]; then
    aws configure set "$key" "$value" --profile "$MEMBER_PROFILE"
  fi
done
aws configure set sso_account_id "$ACCOUNT_ID" --profile "$MEMBER_PROFILE"
aws configure set sso_role_name AdministratorAccess --profile "$MEMBER_PROFILE"
if [[ "$(aws sts get-caller-identity --profile "$MEMBER_PROFILE" --query Account --output text | tr -d '\r')" != "$ACCOUNT_ID" ]]; then
  warn "Stopping: profile $MEMBER_PROFILE didn't reach portfolio."
  exit 1
fi
say "PASS: signed in to portfolio"
pause

stage "Find AInakupo's production database"
CLUSTER_ID=""
for arn in $(aws dsql list-clusters --profile "$MEMBER_PROFILE" --region "$REGION" \
  --query 'clusters[].arn' --output text | tr -d '\r'); do
  name="$(aws dsql list-tags-for-resource --resource-arn "$arn" --profile "$MEMBER_PROFILE" \
    --region "$REGION" --query 'tags.Name' --output text | tr -d '\r')"
  if [[ "$name" == "$CLUSTER_NAME" ]]; then
    CLUSTER_ID="${arn##*/}"
  fi
done
if [[ ! "$CLUSTER_ID" =~ ^[a-z0-9]+$ ]]; then
  warn "Stopping: no DSQL cluster in portfolio is tagged Name=$CLUSTER_NAME."
  exit 1
fi
CLUSTER_ENDPOINT="$CLUSTER_ID.dsql.$REGION.on.aws"
say "PASS: found $CLUSTER_NAME"

FOUND="$(MSYS_NO_PATHCONV=1 aws ssm get-parameters --names "${PARAMS[@]}" --profile "$MEMBER_PROFILE" \
  --region "$REGION" --query 'Parameters[].Name' --output text | tr -d '\r')"
if [[ -n "$FOUND" ]]; then
  note "SSM already has: $FOUND"
  note "keys:add checks the database, not SSM. If $EPISODE has no keys there, it"
  note "overwrites these with new ones. If it does, it refuses and changes nothing."
else
  say "Neither SSM parameter exists yet."
fi
pause

stage "Make the keys"
say "Next: keys:add writes both keys to SSM, then their hashes to the database."
if ! confirm "Make $EPISODE's AInakupo keys now?"; then
  say "Nothing changed."
  exit 0
fi
if ! RESULT="$(CLUSTER_ENDPOINT="$CLUSTER_ENDPOINT" AWS_PROFILE="$MEMBER_PROFILE" \
  AWS_REGION="$REGION" node dist/keys/add.cjs "$EPISODE" 2>&1 | tr -d '\r')"; then
  printf '%s\n' "$RESULT" | sed 's/^/  /'
  warn "keys:add failed. If it says $EPISODE already has keys, nothing changed."
  warn "Otherwise run this wizard again: a failure before the database step"
  warn "leaves only unused keys in SSM, which the rerun overwrites."
  exit 1
fi
printf '%s\n' "$RESULT" | sed 's/^/  /'
pause

stage "Last check"
COUNT="$(MSYS_NO_PATHCONV=1 aws ssm get-parameters --names "${PARAMS[@]}" --profile "$MEMBER_PROFILE" \
  --region "$REGION" --query "length(Parameters[?Type=='SecureString'])" --output text | tr -d '\r')"
if [[ "$COUNT" != "2" ]]; then
  warn "FAIL: SSM doesn't hold both keys as SecureStrings."
  exit 1
fi
say "PASS: both keys are in SSM as SecureStrings"
pause

finish
say "Copy these lines to Claude. They're hints, not keys:"
printf '\n%s\n\n' "$(printf '%s\n' "$RESULT" | sed 's/^/  /')"
}

run_wizard "$@"; exit
